/bin/zsh -lc "python3 - <<'PY'
from math import gcd
facets = [[0,1,2],[0,2,3],[0,1,5],[0,4,5],[0,3,4],[1,2,4],[1,3,4],[1,3,5],[2,3,5],[2,4,5]]
non_tree = [(1,2),(1,3),(1,4),(1,5),(2,3),(2,4),(2,5),(3,4),(3,5),(4,5)]
edge_index = {e:i for i,e in enumerate(non_tree)}
M=[]
for tri in facets:
    a,b,c = tri
    bd = {(b,c):1,(a,c):-1,(a,b):1}
    row=[0]*10
    for (u,v),coef in bd.items():
        e=(u,v) if u<v else (v,u)
        s = coef if u<v else -coef
        if e in edge_index:
            row[edge_index[e]] += s
    M.append(row)
print('M=')
for r in M:
    print(r)

# Bareiss determinant
A=[row[:] for row in M]
n=len(A)
prev=1
sign=1
for k in range(n-1):
    if A[k][k]==0:
        swap=None
        for i in range(k+1,n):
            if A[i][k]"'!=0:
                swap=i; break
        if swap is None:
            print('"'det=0')
            break
        A[k],A[swap]=A[swap],A[k]
        sign*=-1
    pivot=A[k][k]
    for i in range(k+1,n):
        for j in range(k+1,n):
            A[i][j]=(A[i][j]*pivot - A[i][k]*A[k][j])//prev
        A[i][k]=0
    prev=pivot
else:
    print('det=',sign*A[n-1][n-1])
PY"

